import { z } from "zod";
import { parseConfig, type ConfigCategory } from "./parse.js";

const ALLOWED_PROTOCOLS = ["postgres:", "postgresql:"] as const;

function isPostgresUrl(value: string): boolean {
  try {
    const url = new URL(value);
    return (ALLOWED_PROTOCOLS as readonly string[]).includes(url.protocol) && url.hostname !== "";
  } catch {
    return false;
  }
}

/**
 * Prepared for a future migration process. No command in this repository
 * calls loadDatabaseConfig yet: packages/database has no Prisma schema or
 * migration command, and apps/api and apps/worker do not consume a
 * database today. This contract lets a future migration command validate
 * its connection string without inventing a fake integration now. It is
 * exercised directly via `relis-config check database` (see cli.ts) and by
 * relis/tests/integration/runtime-config/.
 */
export const databaseConfigSchema = z.object({
  DATABASE_URL: z.string().min(1).refine(isPostgresUrl, "invalid_database_url"),
});

export type DatabaseConfig = z.infer<typeof databaseConfigSchema>;

export interface RawDatabaseEnv {
  DATABASE_URL?: string;
}

export function loadDatabaseConfig(raw: RawDatabaseEnv): DatabaseConfig {
  return parseConfig("database", databaseConfigSchema, raw, () => "database");
