import { existsSync } from "node:fs";
import path from "node:path";
import dotenv from "dotenv";

/**
 * Server-only: loads dotenv files before an entry point reads
 * process.env. Never import this from public.ts or web browser code.
 */

export type RuntimeMode = "development" | "test" | "production";

/**
 * Loads .env files with Next.js-style precedence (highest first; dotenv
 * never overrides an already-set process.env value, so loading
 * highest-precedence files first makes them win):
 *   .env.<mode>.local (skipped in test) > .env.local (skipped in test)
 *   > .env.<mode> > .env
 */
export function loadEnvFiles(mode: RuntimeMode, cwd: string = process.cwd()): void {
  const candidates = [
    mode !== "test" ? `.env.${mode}.local` : null,
    mode !== "test" ? ".env.local" : null,
    `.env.${mode}`,
    ".env",
  ].filter((file): file is string => file !== null);

  for (const file of candidates) {
    const filePath = path.join(cwd, file);
    if (existsSync(filePath)) {
      dotenv.config({ path: filePath });
    }
  }
}

export function resolveRuntimeMode(rawNodeEnv: string | undefined): RuntimeMode {
  return rawNodeEnv === "production" || rawNodeEnv === "test" ? rawNodeEnv : "development";
}

