#!/usr/bin/env node
import { spawn } from "node:child_process";
import { ConfigValidationError, loadEnvFiles, loadWebRuntimeConfig, resolveRuntimeMode } from "@relis/config";
import { parsePublicWebConfig } from "@relis/config/public";

/**
 * Validates web configuration before Next.js ever opens a listener or
 * starts a build, instead of relying on a lifecycle hook that can run
 * after Next has already started listening.
 *
 * Usage: node scripts/run.mjs <dev|build|start> [extra next args...]
 */

const [, , command, ...rest] = process.argv;
const VALID_COMMANDS = new Set(["dev", "build", "start"]);

if (!VALID_COMMANDS.has(command)) {
  console.error("Usage: node scripts/run.mjs <dev|build|start> [next args...]");
  process.exit(2);
}

const defaultMode = command === "build" ? "production" : "development";
const mode = resolveRuntimeMode(process.env.NODE_ENV ?? defaultMode);
loadEnvFiles(mode);

function fail(error) {
  if (error instanceof ConfigValidationError) {
    console.error(JSON.stringify(error.toDiagnostic()));
    process.exit(1);
  }
  throw error;
}

let webPort;

try {
  // `build` only produces the static/public bundle: it needs the
  // build-time public config, not a runtime listener port.
  if (command !== "build") {
    webPort = loadWebRuntimeConfig(process.env).WEB_PORT;
  }
  // Validated here so a bad value never reaches `next build`/`next dev`
  // output, even though only the client bundle actually consumes it.
  parsePublicWebConfig({ NEXT_PUBLIC_API_URL: process.env.NEXT_PUBLIC_API_URL });
} catch (error) {
  fail(error);
}

const nextArgs = [command, ...rest];
if (webPort !== undefined) {
  nextArgs.push("-p", String(webPort));
}

function quoteArg(value) {
  return /^[\w.-]+$/.test(value) ? value : JSON.stringify(value);
}

// A single quoted command string (rather than shell:true with an argv
// array) avoids Node's shell-argument-escaping deprecation warning; every
// token here is either a fixed literal or a validated port number.
const child = spawn(["next", ...nextArgs.map(quoteArg)].join(" "), {
  stdio: "inherit",
  shell: true,
  env: process.env,
});

child.on("exit", (code, signal) => {
  if (signal) {
    process.kill(process.pid, signal);
    return;
  }
  process.exit(code ?? 1);
});

child.on("error", (error) => {
  console.error(`Failed to start Next.js: ${error.message}`);
  process.exit(1);
});

