const IPV6_CHAR_REGEX = /^[0-9a-fA-F:]+$/;
const HOSTNAME_LABEL = "(?!-)[A-Za-z0-9-]{1,63}(?<!-)";
const HOSTNAME_REGEX = new RegExp(`^${HOSTNAME_LABEL}(\\.${HOSTNAME_LABEL})*$`);

function isValidIpv4(value: string): boolean {
  const match = IPV4_REGEX.exec(value);
  if (!match) return false;
  return match.slice(1).every((octet) => Number(octet) <= 255 && String(Number(octet)) === octet);
}

