import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import dotenv from "dotenv";

/**
 * Server-only: loads dotenv files before an entry point reads
 * process.env. Never import this from public.ts or web browser code.
 */

export type RuntimeMode = "development" | "test" | "production";

// Matches $VAR / ${VAR}, with a leading backslash escaping the whole
// reference to a literal "$VAR" / "${VAR}" (dotenv-expand convention).
const EXPANSION_PATTERN = /(\\)?\$\{([A-Za-z_][A-Za-z0-9_]*)\}|(\\)?\$([A-Za-z_][A-Za-z0-9_]*)/g;

/**
 * Expands $VAR / ${VAR} references. Looks up already-resolved
 * process.env values first (so a higher-precedence file or the real OS
 * environment always wins), then sibling keys from the same file. An
 * unresolved reference expands to an empty string, matching common
 * dotenv-expand semantics; hand-rolled here rather than depending on a
 * third-party package (see README "Environment loading").
 */
function expand(value: string, siblingValues: Record<string, string>): string {
  return value.replace(
    EXPANSION_PATTERN,
    (match, escapedBraced: string | undefined, bracedName: string | undefined, escapedBare: string | undefined, bareName: string | undefined) => {
      if (escapedBraced || escapedBare) return match.slice(1);
      const name = bracedName ?? bareName ?? "";
      return process.env[name] ?? siblingValues[name] ?? "";
    },
  );
}

function loadEnvFile(filePath: string): void {
  const parsed = dotenv.parse(readFileSync(filePath, "utf8"));
  for (const [key, rawValue] of Object.entries(parsed)) {
    // dotenv semantics: an already-set process.env value (the real OS
    // environment, or a higher-precedence file loaded earlier) always wins.
    if (process.env[key] !== undefined) continue;
    process.env[key] = expand(rawValue, parsed);
  }
}

/**
 * Finds the pnpm workspace root by walking up from `startDir` looking for
 * pnpm-workspace.yaml. Falls back to `startDir` itself if none is found
 * (e.g. a package checked out standalone).
 */
export function findWorkspaceRoot(startDir: string): string {
  let dir = path.resolve(startDir);
  for (;;) {
    if (existsSync(path.join(dir, "pnpm-workspace.yaml"))) return dir;
    const parent = path.dirname(dir);
    if (parent === dir) return path.resolve(startDir);
    dir = parent;
  }
}

/**
 * Loads .env files from BOTH the owning package directory (`cwd`, e.g.
 * apps/api) and the application root (the pnpm workspace root), so a
 * shared root-level .env documented in the README and a package-specific
 * override both take effect consistently — instead of each process only
 * ever searching its own directory.
 *
 * Precedence (highest first; dotenv never overrides an already-set
 * process.env value, so loading highest-precedence files first makes them
 * win): for each Next.js-style tier — .env.<mode>.local (skipped in test)
 * > .env.local (skipped in test) > .env.<mode> > .env — the package
 * directory's file wins over the workspace root's file at that same tier.
 *
 * Each loaded file also expands $VAR / ${VAR} references (see `expand`
 * above), matching Next.js's own environment-loading behavior.
 */
export function loadEnvFiles(mode: RuntimeMode, cwd: string = process.cwd()): void {
  const root = findWorkspaceRoot(cwd);
  const resolvedCwd = path.resolve(cwd);
  const directories = resolvedCwd === root ? [resolvedCwd] : [resolvedCwd, root];

  const tiers = [
    mode !== "test" ? `.env.${mode}.local` : null,
    mode !== "test" ? ".env.local" : null,
    `.env.${mode}`,
    ".env",
  ].filter((file): file is string => file !== null);

  const seen = new Set<string>();
  for (const tier of tiers) {
    for (const dir of directories) {
      const filePath = path.join(dir, tier);
      if (seen.has(filePath)) continue;
      seen.add(filePath);
      if (existsSync(filePath)) {
        loadEnvFile(filePath);
      }
    }
  }
}

/**
 * Resolves an explicit NODE_ENV to a supported mode. An absent value
 * falls back to `fallback` (chosen per-command by the caller — e.g.
 * "production" for a production start, "development" for dev). An
 * explicit but unsupported value is NOT silently coerced: it is returned
 * as "development" only for the purposes of choosing which .env files to
 * load — the actual NODE_ENV configuration value is separately validated
 * (and rejected if invalid) by each process's own schema.
 */
export function resolveRuntimeMode(rawNodeEnv: string | undefined, fallback: RuntimeMode = "development"): RuntimeMode {
  if (rawNodeEnv === undefined) return fallback;
  return rawNodeEnv === "production" || rawNodeEnv === "test" || rawNodeEnv === "development" ? rawNodeEnv : "development";
}

