1	import { existsSync, readFileSync } from "node:fs";
2	import path from "node:path";
3	import dotenv from "dotenv";
4	
5	/**
6	 * Server-only: loads dotenv files before an entry point reads
7	 * process.env. Never import this from public.ts or web browser code.
8	 */
9	
10	export type RuntimeMode = "development" | "test" | "production";
11	
12	// Matches $VAR / ${VAR}, with a leading backslash escaping the whole
13	// reference to a literal "$VAR" / "${VAR}" (dotenv-expand convention).
14	const EXPANSION_PATTERN = /(\\)?\$\{([A-Za-z_][A-Za-z0-9_]*)\}|(\\)?\$([A-Za-z_][A-Za-z0-9_]*)/g;
15	
16	/**
17	 * Expands $VAR / ${VAR} references. Looks up the real process.env first
18	 * (so an already-set OS environment variable always wins), then the
19	 * already-precedence-resolved `winners` map — so a reference works
20	 * regardless of whether the referenced variable came from the package
21	 * directory or the workspace root. An unresolved reference expands to an
22	 * empty string, matching common dotenv-expand semantics; hand-rolled here
23	 * rather than depending on a third-party package (see README "Environment
24	 * loading" — a `dotenv-expand` release was found to ship unrelated
25	 * cryptographic primitive code under a suspicious version number and was
26	 * deliberately not used).
27	 */
28	function expand(value: string, winners: Record<string, string>): string {
29	  return value.replace(
30	    EXPANSION_PATTERN,
31	    (match, escapedBraced: string | undefined, bracedName: string | undefined, escapedBare: string | undefined, bareName: string | undefined) => {
32	      if (escapedBraced || escapedBare) return match.slice(1);
33	      const name = bracedName ?? bareName ?? "";
34	      return process.env[name] ?? winners[name] ?? "";
35	    },
36	  );
37	}
38	
39	/**
40	 * Finds the pnpm workspace root by walking up from `startDir` looking for
41	 * pnpm-workspace.yaml. Falls back to `startDir` itself if none is found
42	 * (e.g. a package checked out standalone).
43	 */
44	export function findWorkspaceRoot(startDir: string): string {
45	  let dir = path.resolve(startDir);
46	  for (;;) {
47	    if (existsSync(path.join(dir, "pnpm-workspace.yaml"))) return dir;
48	    const parent = path.dirname(dir);
49	    if (parent === dir) return path.resolve(startDir);
50	    dir = parent;
51	  }
52	}
53	
54	/**
55	 * Loads .env files from BOTH the owning package directory (`cwd`, e.g.
56	 * apps/api) and the application root (the pnpm workspace root), so a
57	 * shared root-level .env documented in the README and a package-specific
58	 * override both take effect consistently — instead of each process only
59	 * ever searching its own directory.
60	 *
61	 * Precedence (highest first; dotenv never overrides an already-set
62	 * process.env value, so loading highest-precedence files first makes them
