// parts) is judged strictly as an IPv4 candidate rather than falling
// through to the generic hostname grammar, which would otherwise accept
// an out-of-range octet like "999.0.0.1" as a syntactically "valid"
// hostname (numeric labels are technically legal hostname labels).
function isDottedQuadShape(value: string): boolean {
  const parts = value.split(".");
  return parts.length === 4 && parts.every((part) => /^\d+$/.test(part));
}

/**
 * A bare listener hostname/IP for binding a server socket: no scheme, no
 * embedded credentials, no path, no port. Rejects a full URL
 * ("http://host"), a value carrying "user:pass@", and other malformed
 * input outright rather than letting it reach the network stack.
 */
export function isValidHostname(value: string): boolean {
  if (value.length === 0 || value.length > 253) return false;
  if (/\s/.test(value)) return false;
  if (value.includes("@")) return false;
  if (value.includes("://")) return false;
  if (value.includes("/")) return false;
  if (isDottedQuadShape(value)) return isValidIpv4(value);
  // Bare (bracket-less) IPv6, e.g. "::1", "fe80::1" — must contain a colon
  // to avoid matching a lone hex-looking hostname label as an address.
  if (value.includes(":") && IPV6_CHAR_REGEX.test(value)) return true;
  if (value.includes(":")) return false;
  return HOSTNAME_REGEX.test(value);
