137	 * environment: `baseEnv` (typically the real OS environment, or a
138	 * fixture/snapshot in tests) merged with every applicable .env file for
139	 * `cwd`, root/package precedence and variable expansion both applied.
140	 * Never mutates `baseEnv` or `process.env` — callers decide what to do
141	 * with the result. This lets two applications (e.g. apps/api and
142	 * apps/web) each resolve their own effective environment independently
143	 * from the SAME starting snapshot, without one's file-derived values
144	 * leaking into the other's resolution.
145	 */
146	export function resolveEffectiveEnv(
147	  mode: RuntimeMode,
148	  cwd: string,
149	  baseEnv: NodeJS.ProcessEnv = process.env,
150	): Record<string, string> {
