201	  return rawNodeEnv === "production" || rawNodeEnv === "test" || rawNodeEnv === "development" ? rawNodeEnv : "development";
202	}
203	
204	const VALID_RUNTIME_MODES: readonly RuntimeMode[] = ["development", "test", "production"];
