213	 * of being silently coerced and then forwarded onward unexamined.
214	 */
215	export function validateRuntimeMode(rawNodeEnv: string | undefined, fallback: RuntimeMode): RuntimeMode {
216	  if (rawNodeEnv === undefined) return fallback;
217	  if ((VALID_RUNTIME_MODES as readonly string[]).includes(rawNodeEnv)) {
218	    return rawNodeEnv as RuntimeMode;
219	  }
220	  throw new ConfigValidationError("web", [{ variable: "NODE_ENV", category: "runtime" }]);
