2	import { spawn } from "node:child_process";
3	import { createRequire } from "node:module";
4	import { ConfigValidationError, loadEnvFiles, loadWebRuntimeConfig, validateRuntimeMode } from "@relis/config";
5	import { parsePublicWebConfig } from "@relis/config/public";
6	
7	/**
8	 * Validates web configuration before Next.js ever opens a listener or
9	 * starts a build, instead of relying on a lifecycle hook that can run
10	 * after Next has already started listening.
11	 *
12	 * Usage: node scripts/run.mjs <dev|build|start> [extra next args...]
13	 */
14	
15	const [, , command, ...rest] = process.argv;
16	const VALID_COMMANDS = new Set(["dev", "build", "start"]);
17	
18	if (!VALID_COMMANDS.has(command)) {
19	  console.error("Usage: node scripts/run.mjs <dev|build|start> [next args...]");
20	  process.exit(2);
21	}
22	
23	function fail(error) {
24	  if (error instanceof ConfigValidationError) {
25	    console.error(JSON.stringify(error.toDiagnostic()));
26	    process.exit(1);
27	  }
28	  throw error;
29	}
30	
31	// "dev" defaults to development; "build" and "start" are both production
32	// artifacts/servers and default to production. An explicit NODE_ENV always
33	// wins over that default, but an explicit, invalid, or empty value is
34	// rejected here rather than silently coerced and forwarded to the spawned
35	// Next.js process unexamined. This first validation determines which
36	// .env.<mode> tier to load and uses only the real OS environment (nothing
37	// has been loaded yet).
38	const defaultMode = command === "dev" ? "development" : "production";
39	let mode;
40	try {
41	  mode = validateRuntimeMode(process.env.NODE_ENV, defaultMode);
42	} catch (error) {
43	  fail(error);
44	}
45	loadEnvFiles(mode);
46	
47	// A .env file can itself define NODE_ENV (it is not special-cased and
48	// follows the same precedence as any other variable), which loadEnvFiles
49	// may just have written into process.env. Re-validate the EFFECTIVE value
50	// — using the tier-selection `mode` as the fallback, so the two stay
51	// consistent whenever no file touches NODE_ENV — before it is forwarded to
52	// the spawned Next.js process. This is what actually closes the gap: an
53	// invalid/empty value introduced by a file is rejected here, not silently
54	// forwarded.
55	let effectiveMode;
56	try {
57	  effectiveMode = validateRuntimeMode(process.env.NODE_ENV, mode);
58	} catch (error) {
59	  fail(error);
60	}
61	// Assign explicitly so the exact validated string is what Next receives,
62	// whether it came from the OS, a file, or the per-command default.
63	process.env.NODE_ENV = effectiveMode;
64	
65	// A single unique sentinel value marks a `-p`/`--port` flag whose value is
66	// missing or looks like another flag (e.g. a trailing `--port`, or
67	// `--port --webpack`) — this must be rejected, not silently ignored by
68	// treating the next flag's name as the port value.
69	const MISSING_PORT_VALUE = Symbol("missing-port-value");
70	
71	// A CLI `-p`/`--port`/`--port=N` override takes precedence over WEB_PORT,
72	// matching Next's own flag. Extracting it here (instead of forwarding both
73	// our own `-p` and the caller's) prevents ever handing Next two
74	// conflicting port arguments. Repeated flags: the last one wins.
75	function extractPortOverride(args) {
76	  let override;
77	  const remaining = [];
78	  for (let i = 0; i < args.length; i++) {
79	    const arg = args[i];
80	    if (arg === "-p" || arg === "--port") {
81	      const next = args[i + 1];
82	      if (next === undefined || next.startsWith("-")) {
83	        override = MISSING_PORT_VALUE;
84	        continue; // `next`, if any, is another flag — do not consume it as a value
85	      }
86	      override = next;
87	      i += 1;
88	      continue;
89	    }
90	    if (arg.startsWith("--port=")) {
91	      override = arg.slice("--port=".length);
92	      continue;
93	    }
94	    remaining.push(arg);
95	  }
96	  return { override, remaining };
97	}
98	
99	const { override: cliPortOverride, remaining: passthroughArgs } = extractPortOverride(rest);
100	
101	let webPort;
102	
103	try {
104	  // `build` only produces the static/public bundle: it needs the
105	  // build-time public config, not a runtime listener port.
106	  if (command !== "build") {
107	    if (cliPortOverride === MISSING_PORT_VALUE) {
108	      throw new ConfigValidationError("web", [{ variable: "WEB_PORT", category: "network" }]);
109	    }
110	    // The CLI override, when present, replaces WEB_PORT entirely — an
111	    // invalid override is rejected even if WEB_PORT itself is valid, and a
112	    // valid override is used even if WEB_PORT itself is invalid.
113	    const resolvedPort = cliPortOverride !== undefined ? cliPortOverride : process.env.WEB_PORT;
114	    webPort = loadWebRuntimeConfig({ WEB_PORT: resolvedPort }).WEB_PORT;
115	  }
116	  // Validated here so a bad value never reaches `next build`/`next dev`
117	  // output, even though only the client bundle actually consumes it.
118	  parsePublicWebConfig({ NEXT_PUBLIC_API_URL: process.env.NEXT_PUBLIC_API_URL });
119	} catch (error) {
120	  fail(error);
121	}
122	
123	const finalArgs = [command, ...passthroughArgs];
124	if (webPort !== undefined) {
125	  finalArgs.push("-p", String(webPort));
126	}
127	
128	// Resolve Next's own entry script and invoke it directly through Node with
129	// an argument array — no shell, no PATH-based ".cmd"/".ps1" resolution, and
130	// no string interpolation of arguments (avoids both injection risk and
131	// Node's shell-argument-escaping deprecation warning).
132	const require = createRequire(import.meta.url);
133	const nextBinPath = require.resolve("next/dist/bin/next");
134	
135	const child = spawn(process.execPath, [nextBinPath, ...finalArgs], {
136	  stdio: "inherit",
137	  env: process.env,
138	});
139	
140	child.on("exit", (code, signal) => {
141	  if (signal) {
142	    process.kill(process.pid, signal);
143	    return;
144	  }
145	  process.exit(code ?? 1);
146	});
147	
148	child.on("error", (error) => {
149	  console.error(`Failed to start Next.js: ${error.message}`);
150	  process.exit(1);
151	});
