23	const here = path.dirname(fileURLToPath(import.meta.url));
24	const repoRoot = path.resolve(here, "../../..");
25	const realWebDir = path.join(repoRoot, "apps", "web");
26	const runScriptPath = path.join(realWebDir, "scripts", "run.mjs");
27	
28	let fixtureRoot: string;
29	let fixtureWebDir: string;
