33	}, 60000);
34	
35	beforeEach(() => {
36	  fixtureRoot = mkdtempSync(path.join(os.tmpdir(), "relis-web-env-fixture-"));
37	  fixtureWebDir = path.join(fixtureRoot, "apps", "web");
38	  mkdirSync(fixtureWebDir, { recursive: true });
39	  // Marks fixtureRoot as the workspace root for findWorkspaceRoot(), fully
40	  // isolating this fixture from the real relis/ workspace root.
41	  writeFileSync(path.join(fixtureRoot, "pnpm-workspace.yaml"), "packages:\n  - apps/*\n");
42	});
43	
44	afterEach(() => {
45	  rmSync(fixtureRoot, { recursive: true, force: true });
46	});
