"use strict";

/**
 * Preloaded via `node --require <this file>` into the REAL apps/web
 * wrapper (scripts/run.mjs) so a test can observe exactly what run.mjs
 * decided to spawn — the command, its arguments, and the relevant
 * forwarded environment variables — without ever launching a real
 * Next.js process or opening a listener.
 *
 * Patches the shared node:child_process module BEFORE run.mjs's own
 * `import { spawn } from "node:child_process"` executes. Node's ESM
 * named imports of core modules are live bindings onto the underlying
 * CommonJS exports object, so this CommonJS-side reassignment (done here,
 * before run.mjs's module graph loads) is what the later ESM call sees.
 *
 * The captured invocation is printed as one line prefixed with
 * "SPAWN_CAPTURED:" followed by JSON, then the process exits immediately
 * — nothing resembling a real child process is ever created.
 */
const childProcess = require("node:child_process");

childProcess.spawn = function interceptedSpawn(command, args, options) {
  const env = (options && options.env) || {};
  process.stdout.write(
    "SPAWN_CAPTURED:" +
      JSON.stringify({
        command,
        args,
        env: {
          NODE_ENV: env.NODE_ENV,
          WEB_PORT: env.WEB_PORT,
          NEXT_PUBLIC_API_URL: env.NEXT_PUBLIC_API_URL,
        },
      }) +
      "\n",
  );
  process.exit(0);
};

