    expect(result.exitCode).toBe(1);
    const diagnostic = parseDiagnostic(result.stderr);
    expect(diagnostic?.variables).toContain("WEB_PORT");
    expect(diagnostic?.variables).not.toContain("NODE_ENV");
  });

  it("lets a real OS NODE_ENV take precedence over a conflicting/invalid value from a .env file", async () => {
    write(fixtureWebDir, ".env", "NODE_ENV=bogus-from-file\n");
    const result = await runWrapper("dev", {
      ...process.env,
      NODE_ENV: "development",
      WEB_PORT: "not-a-number",
    });

    expect(result.exitCode).toBe(1);
    const diagnostic = parseDiagnostic(result.stderr);
    expect(diagnostic?.variables).toContain("WEB_PORT");
    expect(diagnostic?.variables).not.toContain("NODE_ENV");
  });

  it("keeps the mode used for env-file selection and the mode forwarded to Next consistent when NODE_ENV is absent", async () => {
    // Absent everywhere: tier selection uses the "dev" default
    // (development), and since no file touches NODE_ENV, the value
    // ultimately forwarded must be that exact same "development" — proven
    // here by observing that .env.development (not .env.production) is the
    // tier consulted.
    write(fixtureWebDir, ".env.development", "WEB_PORT=not-a-number\n");
    write(fixtureWebDir, ".env.production", "WEB_PORT=also-not-a-number-but-wrong-tier\n");
    const env = { ...process.env };
    delete env.NODE_ENV;
    delete env.WEB_PORT;

    const result = await runWrapper("dev", env);

    expect(result.exitCode).toBe(1);
    const diagnostic = parseDiagnostic(result.stderr);
    expect(diagnostic?.variables).toContain("WEB_PORT");
