1	#!/usr/bin/env node
2	import { spawn } from "node:child_process";
3	import { createRequire } from "node:module";
4	import {
5	  ConfigValidationError,
6	  loadEnvFiles,
7	  loadWebRuntimeConfig,
8	  validateConsistentRuntimeMode,
9	  validateRuntimeMode,
10	} from "@relis/config";
11	import { parsePublicWebConfig } from "@relis/config/public";
12	
13	/**
14	 * Validates web configuration before Next.js ever opens a listener or
15	 * starts a build, instead of relying on a lifecycle hook that can run
16	 * after Next has already started listening.
17	 *
18	 * Usage: node scripts/run.mjs <dev|build|start> [extra next args...]
19	 */
20	
21	const [, , command, ...rest] = process.argv;
22	const VALID_COMMANDS = new Set(["dev", "build", "start"]);
23	
24	if (!VALID_COMMANDS.has(command)) {
25	  console.error("Usage: node scripts/run.mjs <dev|build|start> [next args...]");
26	  process.exit(2);
27	}
28	
29	function fail(error) {
30	  if (error instanceof ConfigValidationError) {
31	    console.error(JSON.stringify(error.toDiagnostic()));
32	    process.exit(1);
33	  }
34	  throw error;
35	}
36	
37	// "dev" defaults to development; "build" and "start" are both production
38	// artifacts/servers and default to production. An explicit NODE_ENV always
39	// wins over that default, but an explicit, invalid, or empty value is
40	// rejected here rather than silently coerced and forwarded to the spawned
41	// Next.js process unexamined. This first validation determines which
42	// .env.<mode> tier to load and uses only the real OS environment (nothing
43	// has been loaded yet).
44	const defaultMode = "production";
45	let mode;
46	try {
47	  mode = validateRuntimeMode(process.env.NODE_ENV, defaultMode);
48	} catch (error) {
49	  fail(error);
50	}
51	loadEnvFiles(mode);
52	
53	// A .env file can itself define NODE_ENV (it is not special-cased and
54	// follows the same precedence as any other variable), which loadEnvFiles
55	// may just have written into process.env. Re-validate the EFFECTIVE value
56	// before it is forwarded to the spawned Next.js process: an invalid/empty
57	// value introduced by a file is rejected, and so is a well-formed but
58	// DIFFERENT mode than the one already used to select which .env.<mode>
59	// tier to load — e.g. `start` loads production-tier files, then a file
60	// sets NODE_ENV=development; accepting that would forward "development"
61	// to Next despite production files being the ones actually loaded. The
62	// mode used for tier selection and the mode forwarded to Next must be
63	// identical; we never silently switch modes after loading files.
64	let effectiveMode;
65	try {
66	  effectiveMode = validateConsistentRuntimeMode(process.env.NODE_ENV, mode);
67	} catch (error) {
68	  fail(error);
69	}
70	// Assign explicitly so the exact validated string is what Next receives,
71	// whether it came from the OS, a file, or the per-command default.
72	process.env.NODE_ENV = effectiveMode;
73	
74	// A single unique sentinel value marks a `-p`/`--port` flag whose value is
75	// missing or looks like another flag (e.g. a trailing `--port`, or
76	// `--port --webpack`) — this must be rejected, not silently ignored by
77	// treating the next flag's name as the port value.
78	const MISSING_PORT_VALUE = Symbol("missing-port-value");
79	
80	// A CLI `-p`/`--port`/`--port=N` override takes precedence over WEB_PORT,
81	// matching Next's own flag. Extracting it here (instead of forwarding both
82	// our own `-p` and the caller's) prevents ever handing Next two
83	// conflicting port arguments. Repeated flags: the last one wins.
84	function extractPortOverride(args) {
85	  let override;
86	  const remaining = [];
87	  for (let i = 0; i < args.length; i++) {
88	    const arg = args[i];
89	    if (arg === "-p" || arg === "--port") {
90	      const next = args[i + 1];
91	      if (next === undefined || next.startsWith("-")) {
92	        override = MISSING_PORT_VALUE;
93	        continue; // `next`, if any, is another flag — do not consume it as a value
94	      }
95	      override = next;
96	      i += 1;
97	      continue;
98	    }
99	    if (arg.startsWith("--port=")) {
100	      override = arg.slice("--port=".length);
101	      continue;
102	    }
103	    remaining.push(arg);
104	  }
105	  return { override, remaining };
106	}
107	
108	const { override: cliPortOverride, remaining: passthroughArgs } = extractPortOverride(rest);
109	
110	let webPort;
111	
112	try {
113	  // `build` only produces the static/public bundle: it needs the
114	  // build-time public config, not a runtime listener port.
115	  if (command !== "build") {
116	    if (cliPortOverride === MISSING_PORT_VALUE) {
117	      throw new ConfigValidationError("web", [{ variable: "WEB_PORT", category: "network" }]);
118	    }
119	    // The CLI override, when present, replaces WEB_PORT entirely — an
120	    // invalid override is rejected even if WEB_PORT itself is valid, and a
121	    // valid override is used even if WEB_PORT itself is invalid.
122	    const resolvedPort = cliPortOverride !== undefined ? cliPortOverride : process.env.WEB_PORT;
123	    webPort = loadWebRuntimeConfig({ WEB_PORT: resolvedPort }).WEB_PORT;
124	  }
125	  // Validated here so a bad value never reaches `next build`/`next dev`
126	  // output, even though only the client bundle actually consumes it.
127	  parsePublicWebConfig({ NEXT_PUBLIC_API_URL: process.env.NEXT_PUBLIC_API_URL });
128	} catch (error) {
129	  fail(error);
130	}
131	
132	const finalArgs = [command, ...passthroughArgs];
133	if (webPort !== undefined) {
134	  finalArgs.push("-p", String(webPort));
135	}
136	
137	// Resolve Next's own entry script and invoke it directly through Node with
138	// an argument array — no shell, no PATH-based ".cmd"/".ps1" resolution, and
139	// no string interpolation of arguments (avoids both injection risk and
140	// Node's shell-argument-escaping deprecation warning).
141	const require = createRequire(import.meta.url);
142	const nextBinPath = require.resolve("next/dist/bin/next");
143	
144	const child = spawn(process.execPath, [nextBinPath, ...finalArgs], {
145	  stdio: "inherit",
146	  env: process.env,
147	});
148	
149	child.on("exit", (code, signal) => {
150	  if (signal) {
151	    process.kill(process.pid, signal);
152	    return;
153	  }
154	  process.exit(code ?? 1);
155	});
156	
157	child.on("error", (error) => {
158	  console.error(`Failed to start Next.js: ${error.message}`);
159	  process.exit(1);
160	});

