    checkPortConflicts(apiEnv, webEnv);
  } catch (error) {
    reportFailure(error);
  }

  console.log(JSON.stringify({ code: "CONFIG_OK", process: "dev (api+web)" }));
}

function main(): void {
  const [command, ...rest] = process.argv.slice(2);

  if (command === "check-ports") {
    runCheckPortsCommand(rest);
    return;
  }

  if (command === "check") {
    runCheckCommand(rest);
    return;
  }

  printUsage();
  process.exit(2);
}

