export function createBuildStep(name, filterArgs, env, options = {}) {
  const spawnFn = options.spawnFn ?? spawn;
  return {
    name: `build:${name}`,
    run: () => spawnAndWait(spawnFn, "pnpm", filterArgs, { stdio: "inherit", shell: true, env, cwd: repoRoot }),
  };
}

