  if (!validation.ok) {
    console.error(JSON.stringify(validation.diagnostic));
    process.exit(1);
  }

  const { apiEnv, webEnv, workerEnv } = validation;

  const steps = [];
  if (!skipMigrate) {
    const controlDatabaseUrl = loadDatabaseConfigForTarget("control", process.env).DATABASE_URL;
    steps.push(createMigrateStep("control", { ...process.env, CONTROL_DATABASE_URL: controlDatabaseUrl }));
  }
