    steps.push(createBuildStep("api", ["--filter", "./apps/api", "build"], apiEnv));
    steps.push(createBuildStep("worker", ["--filter", "@relis/worker", "build"], workerEnv));
    steps.push(createBuildStep("web", ["--filter", "./apps/web", "build"], webEnv));
  }

