  process.on("SIGINT", () => supervisor.requestShutdown("SIGINT"));
  process.on("SIGTERM", () => supervisor.requestShutdown("SIGTERM"));

  const exitCode = await supervisor.exitPromise;
  process.exit(exitCode);
}

if (isMainModule()) {
  main();
}

