export function validateDeployment(baseEnv, options = {}) {
  const mode = validateRuntimeMode(baseEnv.NODE_ENV, "production");
  const apiEnv = resolveEffectiveEnv(mode, apiDir, baseEnv);
  const webEnv = resolveEffectiveEnv(mode, webDir, baseEnv);
  const workerEnv = resolveEffectiveEnv(mode, workerDir, baseEnv);

