    console.log("after shutdown: api open:", await isPortOpen(5011));
    console.log("after shutdown: web open:", await isPortOpen(5010));
    console.log("deploy child exitCode:", child.exitCode, "killed:", child.killed);
    process.exit(0);
  }, 3000);
