/**
 * Spawns every service and supervises the group's lifecycle: if one exits
 * unexpectedly (before a requested shutdown) or fails to spawn, every
 * other running service is killed and the returned promise resolves
 * nonzero; a requested shutdown (SIGINT/SIGTERM) kills every service and
 * resolves 0 once all have exited. `options.spawnFn` is injectable so
 * tests can simulate spawn failures/unexpected exits without launching
 * real processes.
 */
export function startAndSupervise(services, options = {}) {
  const spawnFn = options.spawnFn ?? spawn;
  const children = new Map();
  let shuttingDown = false;
  let settled = false;
  let resolveExit;
  const exitPromise = new Promise((resolve) => {
    resolveExit = resolve;
  });

  function finish(code) {
    if (settled) return;
    settled = true;
    resolveExit(code);
  }

  function shutdownAll(signal) {
    if (shuttingDown) return;
    shuttingDown = true;
    for (const child of children.values()) {
      if (child.exitCode === null && child.signalCode === null) {
        child.kill(signal ?? "SIGTERM");
      }
    }
  }

  for (const service of services) {
    const child = spawnFn(service.command, service.args, {
      stdio: "inherit",
      env: service.env,
      cwd: service.cwd,
    });
    children.set(service.name, child);

    child.on("error", () => {
      console.error(JSON.stringify({ code: "SERVICE_SPAWN_FAILED", service: service.name }));
      shutdownAll();
      finish(1);
    });

    child.on("exit", (code, signal) => {
      children.delete(service.name);
      if (!shuttingDown) {
        console.error(JSON.stringify({ code: "SERVICE_EXITED_UNEXPECTEDLY", service: service.name }));
        shutdownAll();
        finish(code && code !== 0 ? code : 1);
        return;
      }
      if (children.size === 0) {
        finish(0);
      }
      void signal;
    });
  }

  function requestShutdown(signal) {
    shutdownAll(signal);
  }

  return { exitPromise, requestShutdown };
}

input.new_string:
const DEFAULT_SHUTDOWN_GRACE_MS = 5000;

/**
 * Kills `pid` AND every descendant it owns, on both supported platforms,
 * targeting only that specific process (tree) — never anything unrelated:
 *  - Windows: `taskkill /PID <pid> /T /F` walks the OS-maintained
 *    parent/child records and force-terminates the whole tree. This does
 *    not depend on the target cooperating with a signal at all, which
 *    matters because a plain `child.kill(signal)` on Windows only ever
 *    reaches the immediate child (never further descendants), and is not
 *    guaranteed to invoke a registered `process.on(signal)` handler in the
 *    target the way a real POSIX signal delivery would.
 *  - POSIX: sends `signal` to the negative pid (the whole process group),
 *    which requires the child to have been spawned with `detached: true`
 *    (making it its own group leader). Falls back to signaling the single
 *    pid if group-signaling fails (e.g. it was never a group leader).
 * Resolves once the kill has been ISSUED, not once the target has
 * actually exited — callers wait for the tracked child's own "exit" event
 * for that confirmation.
 */
function killProcessTree(pid, signal) {
  return new Promise((resolve) => {
    if (process.platform === "win32") {
      execFile("taskkill", ["/pid", String(pid), "/T", "/F"], () => resolve());
      return;
    }
    try {
      process.kill(-pid, signal);
    } catch {
      try {
        process.kill(pid, signal);
      } catch {
        // Already exited.
      }
    }
    resolve();
  });
}

/**
 * The default spawnFn used by startAndSupervise: spawns detached on POSIX
 * (so the child becomes its own process-group leader and `killProcessTree`
 * can target the whole group) — a no-op distinction on Windows, where tree
 * relationships are tracked by the OS regardless of `detached`.
 */
function defaultSpawnService(command, args, options) {
  const spawnOptions = process.platform === "win32" ? options : { ...options, detached: true };
  return spawn(command, args, spawnOptions);
}

function waitForChildExit(child, timeoutMs) {
  if (child.exitCode !== null || child.signalCode !== null) {
    return Promise.resolve(true);
  }
  return new Promise((resolve) => {
    const timer = setTimeout(() => resolve(false), timeoutMs);
    child.once("exit", () => {
      clearTimeout(timer);
      resolve(true);
    });
  });
}

/**
 * Spawns every service and supervises the group's lifecycle:
 *  - If one fails to spawn or exits unexpectedly (before a requested
 *    shutdown), every other still-running service (and everything each
 *    one owns) is terminated, and the returned promise resolves nonzero
 *    only AFTER every service has been confirmed to have actually exited
 *    (not merely "asked to").
 *  - A requested shutdown (`requestShutdown`, wired to SIGINT/SIGTERM by
 *    the caller) terminates every service the same way and resolves 0
 *    once all have exited.
 *  - Termination is bounded and escalates: a cooperative signal first
 *    (`child.kill(signal)`, giving a well-behaved process — including
 *    apps/web's wrapper, which now forwards it to its own Next child — a
 *    chance to shut down its own tree on its own), then, if the process
 *    (or any part of its tree) is still alive after `gracePeriodMs`, a
 *    forceful, platform-appropriate tree-kill (`killProcessTree`) that
 *    does not depend on cooperation at all.
 *  - Never signals anything beyond the specific pids this function itself
 *    spawned (and their descendants) — no broad or name-based process
 *    lookup is ever used.
 *
 * `options.spawnFn` is injectable so tests can simulate spawn failures
 * without depending on a specific missing executable; `options.killFn` is
 * injectable so lifecycle-ordering tests can observe termination calls
 * without real process trees, while separate tests use the real
 * `killProcessTree` against harmless local fixtures to prove actual OS
 * -level cleanup.
 */
export function startAndSupervise(services, options = {}) {
  const spawnFn = options.spawnFn ?? defaultSpawnService;
  const killFn = options.killFn ?? killProcessTree;
  const gracePeriodMs = options.gracePeriodMs ?? DEFAULT_SHUTDOWN_GRACE_MS;

  const entries = new Map();
  let shuttingDown = false;
  let settled = false;
  let finalCode = 0;
  let resolveExit;
  const exitPromise = new Promise((resolve) => {
    resolveExit = resolve;
  });

  function allExited() {
    for (const entry of entries.values()) {
      if (!entry.exited) return false;
    }
    return true;
  }

  function maybeFinish() {
    if (settled || !allExited()) return;
    settled = true;
    resolveExit(finalCode);
  }

  async function terminate(entry, signal) {
    if (entry.exited) return;
    const { child } = entry;
    if (child.exitCode === null && child.signalCode === null) {
      child.kill(signal ?? "SIGTERM");
    }
    if (await waitForChildExit(child, gracePeriodMs)) return;
    if (entry.exited) return;
    // The cooperative signal did not bring the process (or its tree) down
    // in time: force a platform-appropriate tree-kill instead of waiting
    // indefinitely or leaving anything running.
    await killFn(child.pid, "SIGKILL");
    await waitForChildExit(child, gracePeriodMs);
  }

  function terminateAll(signal) {
    shuttingDown = true;
    return Promise.all([...entries.values()].map((entry) => terminate(entry, signal)));
  }

  for (const service of services) {
    const child = spawnFn(service.command, service.args, {
      stdio: service.stdio ?? "inherit",
      env: service.env,
      cwd: service.cwd,
    });
    const entry = { child, exited: false };
    entries.set(service.name, entry);

    const onError = () => {
      console.error(JSON.stringify({ code: "SERVICE_SPAWN_FAILED", service: service.name }));
      entry.exited = true; // a spawn error means there is no real process to wait for
      finalCode = finalCode || 1;
      if (!shuttingDown) void terminateAll();
      maybeFinish();
    };

    const onExit = () => {
      const wasAlreadyShuttingDown = shuttingDown;
      entry.exited = true;
      if (!wasAlreadyShuttingDown) {
        console.error(JSON.stringify({ code: "SERVICE_EXITED_UNEXPECTEDLY", service: service.name }));
        finalCode = 1;
        void terminateAll();
      }
      maybeFinish();
    };

    child.once("error", onError);
    child.once("exit", onExit);
  }

  function requestShutdown(signal) {
    if (!shuttingDown) void terminateAll(signal);
    return exitPromise;
  }

  maybeFinish(); // handles the (degenerate) zero-services case

  return { exitPromise, requestShutdown };
}

