  const killFn = options.killFn ?? killProcessTree;
  const gracePeriodMs = options.gracePeriodMs ?? DEFAULT_SHUTDOWN_GRACE_MS;

  const entries = new Map();
  let shuttingDown = false;
  let settled = false;
  let finalCode = 0;
  let resolveExit;
  const exitPromise = new Promise((resolve) => {
    resolveExit = resolve;
  });

  function allExited() {
    for (const entry of entries.values()) {
      if (!entry.exited) return false;
    }
    return true;
  }

  function maybeFinish() {
    if (settled || !allExited()) return;
    settled = true;
    resolveExit(finalCode);
  }

  async function terminate(entry, signal) {
    if (entry.exited) return;
    const { child } = entry;
    if (child.exitCode === null && child.signalCode === null) {
      child.kill(signal ?? "SIGTERM");
    }
    if (await waitForChildExit(child, gracePeriodMs)) return;
    if (entry.exited) return;
