import { startAndSupervise } from "../../../../../../OneDrive/Desktop/vibe-coding-exp/relis/tooling/scripts/deploy.mjs";
import path from "node:path";

const fixturesDir = "C:/Users/guinb/OneDrive/Desktop/vibe-coding-exp/relis/tests/fixtures/runtime-config";

function isAlive(pid) {
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

function extractPid(stdout, label) {
  const match = stdout.match(new RegExp(`${label}:(\\d+)`));
  return match ? Number(match[1]) : undefined;
}

async function main() {
  let wrapperStdout = "";
  const services = [
    {
      name: "wrapper",
      command: process.execPath,
      args: [path.join(fixturesDir, "harmless-wrapper.mjs")],
      env: process.env,
      cwd: fixturesDir,
      stdio: "pipe",
    },
  ];

  const supervisor = startAndSupervise(services, { gracePeriodMs: 2000 });

  // Give the wrapper+grandchild a moment to start, then find their pids by
  // hooking stdout via the injected spawnFn indirectly: simplest here is to
  // just wait, then use a real spawn on the side isn't quite right - so
  // instead use options.spawnFn to capture the child object.
  await new Promise((r) => setTimeout(r, 1500));

  console.log("requesting shutdown...");
  const start = Date.now();
  await supervisor.requestShutdown("SIGTERM");
  console.log("shutdown resolved after", Date.now() - start, "ms");
}

main();

