  // forward the signal to its own Next.js child. This step is what
  // actually guarantees no descendant survives; it is a cheap no-op
  // when the tree is already fully gone.
  if (pid !== undefined) {
    await killFn(pid, "SIGKILL");
    await waitForChildExit(child, gracePeriodMs);
  }
}

