async function terminate(entry, signal) {
  if (entry.exited) return;
  const { child } = entry;
  const pid = child.pid;

  if (process.platform === "win32") {
    // On Windows, child.kill(signal) for any non-SIGKILL signal
    // terminates the DIRECT child immediately, regardless of any
    // handler it registered (confirmed: a registered SIGTERM handler
    // never runs). By the time it has exited, Windows can no longer
    // enumerate its children by parent pid to clean them up — a
    // "cooperative signal, escalate on timeout" ordering would kill the
    // parent before its own descendants could ever be found. Run the
    // guaranteed tree-kill FIRST instead, while the process (and its
    // recorded parent/child relationships) still exist.
    if (pid !== undefined) {
      await killFn(pid, "SIGKILL");
    }
    await waitForChildExit(child, gracePeriodMs);
    return;
  }

  // POSIX: a real signal delivered to the child (and, since it is
  // spawned as its own process-group leader, forwarded to its whole
  // group) gives a well-behaved process a genuine chance to shut itself
  // — and everything it owns — down cooperatively first.
  if (child.exitCode === null && child.signalCode === null) {
    child.kill(signal ?? "SIGTERM");
  }
  if (await waitForChildExit(child, gracePeriodMs)) return;
  // The cooperative signal did not bring the process (or its tree) down
  // in time: force a guaranteed tree-kill instead of waiting
  // indefinitely or leaving anything running.
  if (pid !== undefined) {
    await killFn(pid, "SIGKILL");
    await waitForChildExit(child, gracePeriodMs);

