import { spawn } from "node:child_process";
import path from "node:path";
import { pathToFileURL } from "node:url";
const { startAndSupervise } = await import(
  pathToFileURL("C:/Users/guinb/OneDrive/Desktop/vibe-coding-exp/relis/tooling/scripts/deploy.mjs").href
);

const fixturesDir = "C:/Users/guinb/OneDrive/Desktop/vibe-coding-exp/relis/tests/fixtures/runtime-config";

function isAlive(pid) {
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

async function main() {
  let wrapperChild;
  let wrapperStdout = "";

  function spawnFn(command, args, options) {
    const child = spawn(command, args, { ...options, stdio: ["ignore", "pipe", "inherit"] });
    wrapperChild = child;
    child.stdout.on("data", (chunk) => {
      wrapperStdout += chunk.toString();
      process.stdout.write(chunk);
    });
    return child;
  }

  const services = [
    {
      name: "wrapper",
      command: process.execPath,
      args: [path.join(fixturesDir, "harmless-wrapper.mjs"), "--detach-child"],
      env: process.env,
      cwd: fixturesDir,
    },
  ];

  const supervisor = startAndSupervise(services, { gracePeriodMs: 1500, spawnFn });

  await new Promise((r) => setTimeout(r, 1500));

  const wrapperPidMatch = wrapperStdout.match(/WRAPPER_PID:(\d+)/);
  const childPidMatch = wrapperStdout.match(/CHILD_PID:(\d+)/);
  const wrapperPid = wrapperPidMatch ? Number(wrapperPidMatch[1]) : wrapperChild.pid;
  const childPid = childPidMatch ? Number(childPidMatch[1]) : undefined;

  console.log("wrapperPid:", wrapperPid, "alive:", isAlive(wrapperPid));
  console.log("childPid:", childPid, "alive:", isAlive(childPid));

  console.log("--- requesting shutdown ---");
  const start = Date.now();
  const exitCode = await supervisor.requestShutdown("SIGTERM");
  console.log("shutdown resolved after", Date.now() - start, "ms, exitCode:", exitCode);

  console.log("after shutdown: wrapperPid alive:", isAlive(wrapperPid));
  console.log("after shutdown: childPid alive:", isAlive(childPid));

  process.exit(0);
}

main();

