62	/**
63	 * Resolves every selected process's effective configuration independently
64	 * from the SAME base environment snapshot (mirroring check-ports — see
65	 * packages/config/src/ports.ts): apps/api, apps/web, apps/worker, AND the
66	 * control database (packages/database), each via `resolveEffectiveEnv`
67	 * with the same root/package/tier precedence the standalone entry points
68	 * themselves use — not read directly from `baseEnv`/`process.env`, which
69	 * would silently ignore any `.env` file those entry points would
70	 * otherwise have honored.
71	 *
72	 * Validates each with its own existing schema (no duplicated rules), plus
73	 * apps/web's additional NODE_ENV-consistency rule (the same one
74	 * apps/web/scripts/run.mjs enforces on itself), and checks for a port
75	 * conflict between apps/api and apps/web. Nothing is spawned as part of
76	 * this function: a failure here — including a failure to even RESOLVE an
77	 * environment, not just to validate one — must prevent every subsequent
78	 * build/migrate/start step, and is always reported as a safe diagnostic,
79	 * never a raw exception or value.
80	 *
81	 * On success, every returned env has its NODE_ENV explicitly set to the
82	 * exact `mode` used here for tier selection. Each entry point re-runs its
83	 * own (lenient) env-file resolution when it starts; explicitly forcing
84	 * NODE_ENV to the already-decided mode means that re-resolution can only
85	 * ever confirm the same mode, never silently diverge to a different one.
86	 */
87	export function validateDeployment(baseEnv, options = {}) {
88	  const mode = validateRuntimeMode(baseEnv.NODE_ENV, "production");
89	
90	  let apiEnv;
91	  let webEnv;
92	  let workerEnv;
93	  let databaseEnv;
94	
