106	    // invalid/empty/conflicting file-provided NODE_ENV must be rejected
107	    // here too, before any deployment side effect — not only when
108	    // apps/web happens to be started directly.
109	    validateConsistentRuntimeMode(webEnv.NODE_ENV, mode);
110	    checkPortConflicts(apiEnv, webEnv);
111	    if (!options.skipMigrate) {
112	      // Only the control database is migrated automatically here: the
113	      // project schema is applied per-project (see README "Migration"),
114	      // not as a single global deploy step, and is out of scope.
115	      loadDatabaseConfigForTarget("control", databaseEnv);
116	    }
117	  } catch (error) {
118	    if (error instanceof ConfigValidationError || error instanceof PortConflictError) {
119	      return { ok: false, diagnostic: error.toDiagnostic(), mode, apiEnv, webEnv, workerEnv, databaseEnv };
120	    }
121	    // An unexpected failure (e.g. an I/O error resolving a .env file)
122	    // must still produce a safe, value-free diagnostic instead of letting
123	    // a raw exception — and whatever it might contain — propagate.
124	    return {
125	      ok: false,
126	      diagnostic: { code: "CONFIG_INVALID", process: "deploy", categories: ["runtime"], variables: [] },
127	      mode,
128	      apiEnv,
129	      webEnv,
130	      workerEnv,
131	      databaseEnv,
132	    };
133	  }
134	
135	  apiEnv.NODE_ENV = mode;
136	  webEnv.NODE_ENV = mode;
137	  workerEnv.NODE_ENV = mode;
138	  databaseEnv.NODE_ENV = mode;
139	
140	  return { ok: true, diagnostic: null, mode, apiEnv, webEnv, workerEnv, databaseEnv };
141	}
