143	function spawnAndWait(spawnFn, command, args, options) {
144	  return new Promise((resolve, reject) => {
145	    const child = spawnFn(command, args, options);
146	    child.on("error", reject);
147	    child.on("exit", (code, signal) => resolve(signal ? 1 : (code ?? 1)));
148	  });
