153	 * never invoking any later step. Pure orchestration with no knowledge of
154	 * what a step actually does — this is the seam tests use with injected
155	 * fake steps to prove ordering and failure propagation without running
156	 * any real build, migration, or process.
157	 */
158	export async function runSteps(steps) {
159	  for (const step of steps) {
160	    const exitCode = await step.run();
161	    if (exitCode !== 0) {
