222	 * Resolves once the kill has been ISSUED, not once the target has
223	 * actually exited — callers wait for the tracked child's own "exit" event
224	 * for that confirmation.
225	 */
226	function killProcessTree(pid, signal) {
227	  return new Promise((resolve) => {
