269	/**
270	 * Spawns every service and supervises the group's lifecycle:
271	 *  - If one fails to spawn or exits unexpectedly (before a requested
272	 *    shutdown), every other still-running service (and everything each
273	 *    one owns) is terminated, and the returned promise resolves nonzero
274	 *    only AFTER every service has been confirmed to have actually exited
275	 *    (not merely "asked to").
276	 *  - A requested shutdown (`requestShutdown`, wired to SIGINT/SIGTERM by
277	 *    the caller) terminates every service the same way and resolves 0
278	 *    once all have exited.
279	 *  - Termination is bounded, in two steps, and the second step ALWAYS
280	 *    runs regardless of how the first went: (1) a cooperative signal
281	 *    (`child.kill(signal)`), giving a well-behaved process — including
282	 *    apps/web's wrapper, which forwards it to its own Next child — a
283	 *    chance to shut down its own tree on its own, bounded by
284	 *    `gracePeriodMs`; then (2) an unconditional, platform-appropriate
285	 *    tree-kill (`killProcessTree`) targeting the same pid. Step 2 is not
286	 *    an "if step 1 failed" escalation: a direct child can appear to exit
287	 *    immediately (on Windows, a non-SIGKILL signal terminates the direct
288	 *    child outright, before it can forward anything to what it spawned)
289	 *    while still leaving a descendant it owns running — step 2 is what
290	 *    actually guarantees no descendant survives, and is a cheap no-op
291	 *    when the tree is already fully gone.
292	 *  - Never signals anything beyond the specific pids this function itself
293	 *    spawned (and their descendants) — no broad or name-based process
294	 *    lookup is ever used.
295	 *
296	 * `options.spawnFn` is injectable so tests can simulate spawn failures
297	 * without depending on a specific missing executable; `options.killFn` is
298	 * injectable so lifecycle-ordering tests can observe termination calls
299	 * without real process trees, while separate tests use the real
300	 * `killProcessTree` against harmless local fixtures to prove actual OS
301	 * -level cleanup.
302	 */
303	export function startAndSupervise(services, options = {}) {
304	  const spawnFn = options.spawnFn ?? defaultSpawnService;
305	  const killFn = options.killFn ?? killProcessTree;
306	  const gracePeriodMs = options.gracePeriodMs ?? DEFAULT_SHUTDOWN_GRACE_MS;
307	
308	  const entries = new Map();
309	  let shuttingDown = false;
310	  let settled = false;
311	  let finalCode = 0;
312	  let resolveExit;
313	  const exitPromise = new Promise((resolve) => {
314	    resolveExit = resolve;
315	  });
316	
317	  function allExited() {
318	    for (const entry of entries.values()) {
319	      if (!entry.exited) return false;
320	    }
321	    return true;
322	  }
323	
324	  function maybeFinish() {
325	    if (settled || !allExited()) return;
326	    settled = true;
327	    resolveExit(finalCode);
328	  }
329	
330	  async function terminate(entry, signal) {
331	    if (entry.exited) return;
332	    const { child } = entry;
333	    const pid = child.pid;
334	
335	    if (process.platform === "win32") {
336	      // On Windows, child.kill(signal) for any non-SIGKILL signal
337	      // terminates the DIRECT child immediately, regardless of any
338	      // handler it registered (confirmed: a registered SIGTERM handler
339	      // never runs). By the time it has exited, Windows can no longer
340	      // enumerate its children by parent pid to clean them up — a
341	      // "cooperative signal, escalate on timeout" ordering would kill the
342	      // parent before its own descendants could ever be found. Run the
343	      // guaranteed tree-kill FIRST instead, while the process (and its
344	      // recorded parent/child relationships) still exist. Still also call
345	      // child.kill() itself afterward: harmless (a no-op) once the tree-kill
346	      // has already terminated the process, and it is what a test's
347	      // injected fake child relies on to simulate its own exit.
