353	      }
354	      await waitForChildExit(child, gracePeriodMs);
355	      return;
356	    }
357	
358	    // POSIX: signal the whole process group (this child was spawned as
359	    // its own group leader — see defaultSpawnService), not just the
360	    // direct child, so a well-behaved process AND everything it owns gets
361	    // a genuine chance to shut down cooperatively first.
362	    if (child.exitCode === null && child.signalCode === null) {
363	      try {
364	        process.kill(-pid, signal ?? "SIGTERM");
365	      } catch {
366	        child.kill(signal ?? "SIGTERM");
367	      }
368	    }
369	    if (await waitForChildExit(child, gracePeriodMs)) return;
370	    // The cooperative signal did not bring the process (or its tree) down
371	    // in time: force a guaranteed tree-kill instead of waiting
372	    // indefinitely or leaving anything running.
373	    if (pid !== undefined) {
374	      await killFn(pid, "SIGKILL");
375	      await waitForChildExit(child, gracePeriodMs);
376	    }
