384	  for (const service of services) {
385	    const child = spawnFn(service.command, service.args, {
386	      stdio: service.stdio ?? "inherit",
387	      env: service.env,
388	      cwd: service.cwd,
389	    });
390	    const entry = { child, exited: false };
391	    entries.set(service.name, entry);
