import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import dotenv from "dotenv";
import { ConfigValidationError } from "./errors.js";

/**
 * Server-only: loads dotenv files before an entry point reads
 * process.env. Never import this from public.ts or web browser code.
 */

export type RuntimeMode = "development" | "test" | "production";

// Matches $VAR / ${VAR}, with a leading backslash escaping the whole
// reference to a literal "$VAR" / "${VAR}" (dotenv-expand convention).
const EXPANSION_PATTERN = /(\\)?\$\{([A-Za-z_][A-Za-z0-9_]*)\}|(\\)?\$([A-Za-z_][A-Za-z0-9_]*)/g;

/**
 * Finds the pnpm workspace root by walking up from `startDir` looking for
 * pnpm-workspace.yaml. Falls back to `startDir` itself if none is found
 * (e.g. a package checked out standalone).
 */
export function findWorkspaceRoot(startDir: string): string {
  let dir = path.resolve(startDir);
  for (;;) {
    if (existsSync(path.join(dir, "pnpm-workspace.yaml"))) return dir;
    const parent = path.dirname(dir);
    if (parent === dir) return path.resolve(startDir);
    dir = parent;
  }
}

function candidateFiles(mode: RuntimeMode, cwd: string): string[] {
  const root = findWorkspaceRoot(cwd);
  const resolvedCwd = path.resolve(cwd);
  const directories = resolvedCwd === root ? [resolvedCwd] : [resolvedCwd, root];

  // Matches installed Next.js behavior: .env.test.local IS loaded in test
  // mode (only the generic .env.local is skipped there, since tests should
  // produce the same results for everyone regardless of a developer's
  // local overrides).
  const tiers = [
    `.env.${mode}.local`,
    mode !== "test" ? ".env.local" : null,
    `.env.${mode}`,
    ".env",
  ].filter((file): file is string => file !== null);

  const files: string[] = [];
  const seen = new Set<string>();
  for (const tier of tiers) {
    for (const dir of directories) {
      const filePath = path.join(dir, tier);
      if (seen.has(filePath)) continue;
      seen.add(filePath);
      files.push(filePath);
    }
  }
  return files;
}

/**
 * Determines the winning RAW (unexpanded) value per key across every
 * candidate file, in precedence order (highest first): for each
 * Next.js-style tier — .env.<mode>.local > .env.local (skipped in test
 * mode only) > .env.<mode> > .env — the package directory's file wins over
 * the workspace root's file at that same tier. First match per key wins;
 * later files never override an earlier winner.
 */
function collectWinners(mode: RuntimeMode, cwd: string): Record<string, string> {
  const winners: Record<string, string> = {};
  for (const filePath of candidateFiles(mode, cwd)) {
    if (!existsSync(filePath)) continue;
    const parsed = dotenv.parse(readFileSync(filePath, "utf8"));
    for (const [key, value] of Object.entries(parsed)) {
      if (!(key in winners)) winners[key] = value;
    }
  }
  return winners;
}

/**
 * Resolves `name`'s fully-expanded value, deterministically, regardless of
 * where in `winners` it happens to be declared:
 *  - An already-resolved base/OS value always wins outright and is
 *    returned as-is (base values are never templates to re-expand).
 *  - A winner's raw value is expanded on demand, recursively resolving any
 *    reference it contains first (memoized in `resolved`), so a chain like
 *    C=${B}, B=${A}, A=resolved converges to the same result regardless of
 *    declaration order.
 *  - A reference to a name that is neither a base value nor a winner
 *    expands to an empty string (documented unresolved-reference
 *    behavior).
 *  - A direct or indirect cycle (name re-entered while already being
 *    resolved) throws a safe ConfigValidationError — naming only the
 *    variable, never a value — instead of recursing forever or returning a
 *    partially-expanded string.
 */
function resolveValue(
  name: string,
  winners: Record<string, string>,
  base: Record<string, string>,
  resolved: Map<string, string>,
  inProgress: Set<string>,
): string {
  const baseValue = base[name];
  if (baseValue !== undefined) return baseValue;

  const cached = resolved.get(name);
  if (cached !== undefined) return cached;

  const raw = winners[name];
  if (raw === undefined) return "";

  if (inProgress.has(name)) {
    throw new ConfigValidationError("env", [{ variable: name, category: "runtime" }]);
  }
  inProgress.add(name);

  const expanded = raw.replace(
    EXPANSION_PATTERN,
    (
      match,
      escapedBraced: string | undefined,
      bracedName: string | undefined,
      escapedBare: string | undefined,
      bareName: string | undefined,
    ) => {
      if (escapedBraced || escapedBare) return match.slice(1);
      const referenced = bracedName ?? bareName ?? "";
      return resolveValue(referenced, winners, base, resolved, inProgress);
    },
  );

  inProgress.delete(name);
  resolved.set(name, expanded);
  return expanded;
}

/**
 * Pure computation of an application's fully resolved effective
 * environment: `baseEnv` (typically the real OS environment, or a
 * fixture/snapshot in tests) merged with every applicable .env file for
 * `cwd`, root/package precedence and variable expansion both applied.
 * Never mutates `baseEnv` or `process.env` — callers decide what to do
 * with the result. This lets two applications (e.g. apps/api and
 * apps/web) each resolve their own effective environment independently
 * from the SAME starting snapshot, without one's file-derived values
 * leaking into the other's resolution.
 */
export function resolveEffectiveEnv(
  mode: RuntimeMode,
  cwd: string,
  baseEnv: NodeJS.ProcessEnv = process.env,
): Record<string, string> {
  const base: Record<string, string> = {};
  for (const [key, value] of Object.entries(baseEnv)) {
    if (value !== undefined) base[key] = value;
  }

  const winners = collectWinners(mode, cwd);
  const resolved = new Map<string, string>();
  const result: Record<string, string> = { ...base };

  for (const key of Object.keys(winners)) {
    if (result[key] !== undefined) continue; // base/OS value always wins outright
    result[key] = resolveValue(key, winners, base, resolved, new Set());
  }

  return result;
}

/**
 * Loads .env files from BOTH the owning package directory (`cwd`, e.g.
 * apps/api) and the application root (the pnpm workspace root), so a
 * shared root-level .env documented in the README and a package-specific
 * override both take effect consistently — instead of each process only
 * ever searching its own directory. Mutates the real process.env in
 * place: intended for a single process's own startup, where process.env
 * genuinely IS that process's environment. Use `resolveEffectiveEnv`
 * instead when two applications' environments must be computed
 * independently (see packages/config/src/cli.ts's `check-ports` command).
 */
export function loadEnvFiles(mode: RuntimeMode, cwd: string = process.cwd()): void {
  const effective = resolveEffectiveEnv(mode, cwd, process.env);
  for (const [key, value] of Object.entries(effective)) {
    if (process.env[key] === undefined) {
      process.env[key] = value;
    }
  }
}

/**
 * Resolves an explicit NODE_ENV to a supported mode for the purpose of
 * choosing which .env files to load. An absent value falls back to
 * `fallback` (chosen per-command by the caller — e.g. "production" for a
 * production start, "development" for dev). An explicit but unsupported
 * value is NOT rejected here — it is treated as "development" only for
 * this file-selection purpose. Use `validateRuntimeMode` instead wherever
 * the resolved mode will also be forwarded to something else (e.g. a
 * spawned child process): that variant rejects an invalid/empty explicit
 * value instead of silently coercing it.
 */
export function resolveRuntimeMode(rawNodeEnv: string | undefined, fallback: RuntimeMode = "development"): RuntimeMode {
  if (rawNodeEnv === undefined) return fallback;
  return rawNodeEnv === "production" || rawNodeEnv === "test" || rawNodeEnv === "development" ? rawNodeEnv : "development";
}

const VALID_RUNTIME_MODES: readonly RuntimeMode[] = ["development", "test", "production"];

/**
 * Strictly resolves NODE_ENV for a command whose resolved mode is also
 * forwarded onward (e.g. apps/web's dev/build/start wrapper, which passes
 * process.env — including NODE_ENV — to the spawned Next.js process). An
 * absent value uses `fallback`. An explicit value must be exactly
 * "development", "test", or "production" — an empty/whitespace-only or
 * otherwise invalid explicit value throws a ConfigValidationError instead
 * of being silently coerced and then forwarded onward unexamined.
 *
 * `processName` labels the resulting diagnostic (default "web", matching
 * this function's original caller, apps/web/scripts/run.mjs); pass the
 * actual caller's identity (e.g. "deploy") so a diagnostic accurately
 * names where the invalid value was rejected.
 */
export function validateRuntimeMode(
  rawNodeEnv: string | undefined,
  fallback: RuntimeMode,
  processName = "web",
): RuntimeMode {
  if (rawNodeEnv === undefined) return fallback;
  if ((VALID_RUNTIME_MODES as readonly string[]).includes(rawNodeEnv)) {
    return rawNodeEnv as RuntimeMode;
  }
  throw new ConfigValidationError(processName, [{ variable: "NODE_ENV", category: "runtime" }]);
}

/**
 * Re-validates NODE_ENV after .env files have been loaded, so the mode
 * used to select which .env.<mode> tier to load (`selectedMode`, resolved
 * via `validateRuntimeMode` BEFORE `loadEnvFiles` ran) and the mode
 * ultimately forwarded onward (e.g. to a spawned Next.js process) can
 * never diverge.
 *
 * A .env file is not special-cased for NODE_ENV — it can set it like any
 * other variable if the OS environment did not already. If it is still
 * absent after loading, `selectedMode` is used unchanged (by
 * construction: `rawNodeEnv` is only ever absent here when the OS did not
 * set it, since an OS-set value would already equal `selectedMode`). If
 * it is present, it must be both valid (delegated to `validateRuntimeMode`
 * — rejects an invalid/empty explicit value) AND equal to `selectedMode`:
 * a well-formed but DIFFERENT mode is rejected too, rather than silently
 * switching modes after the fact — e.g. `start` selects and loads
 * production-tier files, then a file sets NODE_ENV=development, which
 * would otherwise forward "development" to Next despite production files
 * having been the ones actually loaded.
 */
export function validateConsistentRuntimeMode(
  rawNodeEnv: string | undefined,
  selectedMode: RuntimeMode,
  processName = "web",
): RuntimeMode {
  const candidate = validateRuntimeMode(rawNodeEnv, selectedMode, processName);
  if (candidate !== selectedMode) {
    throw new ConfigValidationError(processName, [{ variable: "NODE_ENV", category: "runtime" }]);
  }
  return candidate;
}

import { afterEach, beforeAll, beforeEach, describe, expect, it } from "vitest";
import { execSync } from "node:child_process";
import { existsSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { validateDeployment } from "../../../tooling/scripts/deploy.mjs";
import { runToCompletion } from "@relis/test-utils";

// Items 1 & 2: deploy.mjs must resolve the control-database's effective
// environment the SAME way (root/package env-file precedence, OS
// precedence) the standalone migration entry point does — not read
// CONTROL_DATABASE_URL directly from process.env — and must enforce
// apps/web's NODE_ENV-consistency rule before any deployment side effect,
// including migration.
//
// tooling/scripts/deploy.mjs resolves apps/api, apps/web, apps/worker, and
// packages/database by their real, fixed repository paths (this mirrors
// how it is actually invoked in production — those paths are not
// parameterized). Proving root/package env-file precedence therefore
// means writing temporary, gitignored `.env*` files into those REAL
// directories and always removing them afterward, even if an assertion
// fails — never leaving one behind. This repository has no real `.env`
// files in these directories (verified before this suite existed), so
// these tests cannot clobber real configuration.

const here = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(here, "../../..");
const databaseDir = path.join(repoRoot, "packages", "database");
const webDir = path.join(repoRoot, "apps", "web");
const deployScriptPath = path.join(repoRoot, "tooling", "scripts", "deploy.mjs");
const spawnInterceptorPath = path.join(repoRoot, "tests", "fixtures", "runtime-config", "spawn-interceptor.cjs");

const VALID_BASE_ENV = {
  API_PORT: "5301",
  WEB_PORT: "5300",
  API_CORS_ORIGIN: "http://localhost:5300",
  NEXT_PUBLIC_API_URL: "http://localhost:5301",
};

const managedFiles: string[] = [];

function writeManaged(filePath: string, content: string): void {
  if (existsSync(filePath)) {
    throw new Error(`Refusing to overwrite a pre-existing file: ${filePath}`);
  }
  writeFileSync(filePath, content);
  managedFiles.push(filePath);
}

afterEach(() => {
  for (const filePath of managedFiles.splice(0)) {
    rmSync(filePath, { force: true });
  }
});

describe("validateDeployment: control-database env resolution (isolated, real repo paths)", () => {
  it("resolves CONTROL_DATABASE_URL from a root-level .env file", () => {
    writeManaged(path.join(repoRoot, ".env"), "CONTROL_DATABASE_URL=postgresql://u:p@localhost:5432/from_root\n");

    const env = { ...VALID_BASE_ENV };
    const result = validateDeployment(env);

    expect(result.ok).toBe(true);
    expect(result.databaseEnv.CONTROL_DATABASE_URL).toBe("postgresql://u:p@localhost:5432/from_root");
  });

  it("lets a package-level (packages/database/.env) value override the root file", () => {
    writeManaged(path.join(repoRoot, ".env"), "CONTROL_DATABASE_URL=postgresql://u:p@localhost:5432/from_root\n");
    writeManaged(path.join(databaseDir, ".env"), "CONTROL_DATABASE_URL=postgresql://u:p@localhost:5432/from_package\n");

    const result = validateDeployment({ ...VALID_BASE_ENV });

    expect(result.ok).toBe(true);
    expect(result.databaseEnv.CONTROL_DATABASE_URL).toBe("postgresql://u:p@localhost:5432/from_package");
  });

  it("lets a real OS/base environment variable take precedence over any file", () => {
    writeManaged(path.join(databaseDir, ".env"), "CONTROL_DATABASE_URL=postgresql://u:p@localhost:5432/from_file\n");

    const result = validateDeployment({
      ...VALID_BASE_ENV,
      CONTROL_DATABASE_URL: "postgresql://u:p@localhost:5432/from_os",
    });

    expect(result.ok).toBe(true);
    expect(result.databaseEnv.CONTROL_DATABASE_URL).toBe("postgresql://u:p@localhost:5432/from_os");
  });

  it("rejects a missing CONTROL_DATABASE_URL (no file, no OS variable) before any side effect", () => {
    const result = validateDeployment({ ...VALID_BASE_ENV });

    expect(result.ok).toBe(false);
    expect(result.diagnostic).toMatchObject({ code: "CONFIG_INVALID", process: "database (control)" });
  });

  it("rejects an invalid CONTROL_DATABASE_URL introduced by a file", () => {
    writeManaged(path.join(databaseDir, ".env"), "CONTROL_DATABASE_URL=not-a-connection-string\n");

    const result = validateDeployment({ ...VALID_BASE_ENV });

    expect(result.ok).toBe(false);
    expect(result.diagnostic).toMatchObject({ code: "CONFIG_INVALID", process: "database (control)" });
  });

  it("forces the resolved databaseEnv's NODE_ENV to the exact mode used for tier selection (consistency with the standalone migrate entry point)", () => {
    writeManaged(path.join(databaseDir, ".env"), "CONTROL_DATABASE_URL=postgresql://u:p@localhost:5432/c\n");

    const result = validateDeployment({ ...VALID_BASE_ENV, NODE_ENV: "test" });

    expect(result.ok).toBe(true);
    expect(result.mode).toBe("test");
    expect(result.databaseEnv.NODE_ENV).toBe("test");
  });

  it("does not require CONTROL_DATABASE_URL when migration is an explicitly unselected step", () => {
    const result = validateDeployment({ ...VALID_BASE_ENV }, { skipMigrate: true });
    expect(result.ok).toBe(true);
  });
});

describe("validateDeployment: web NODE_ENV consistency enforced before any deployment side effect", () => {
  it("rejects a conflicting file-provided web NODE_ENV even when the database and every other process are valid", () => {
    writeManaged(path.join(webDir, ".env"), "NODE_ENV=development\n"); // conflicts with deployment's own "production" default
    writeManaged(path.join(databaseDir, ".env"), "CONTROL_DATABASE_URL=postgresql://u:p@localhost:5432/c\n");

    const result = validateDeployment({ ...VALID_BASE_ENV });

    expect(result.ok).toBe(false);
    expect(result.diagnostic).toMatchObject({ code: "CONFIG_INVALID", process: "web" });
    expect(result.diagnostic.variables).toContain("NODE_ENV");
  });

  it("rejects an empty file-provided web NODE_ENV", () => {
    writeManaged(path.join(webDir, ".env"), "NODE_ENV=\n");

    const result = validateDeployment({ ...VALID_BASE_ENV, CONTROL_DATABASE_URL: "postgresql://u:p@localhost:5432/c" });

    expect(result.ok).toBe(false);
    expect(result.diagnostic.variables).toContain("NODE_ENV");
  });

  it("accepts a file-provided web NODE_ENV that matches the deployment mode", () => {
    writeManaged(path.join(webDir, ".env"), "NODE_ENV=production\n");

    const result = validateDeployment({ ...VALID_BASE_ENV, CONTROL_DATABASE_URL: "postgresql://u:p@localhost:5432/c" });

    expect(result.ok).toBe(true);
  });
});

describe("tooling/scripts/deploy.mjs: real subprocess — invalid web config prevents migration too (zero spawn calls)", () => {
  beforeAll(() => {
    execSync("pnpm --filter @relis/config build", { cwd: repoRoot, stdio: "pipe" });
  }, 60000);

  function parseCaptured(stdout: string) {
    const line = stdout.split("\n").find((entry) => entry.startsWith("SPAWN_CAPTURED:"));
    return line ? JSON.parse(line.slice("SPAWN_CAPTURED:".length)) : null;
  }

  it("never invokes the migration step (or anything else) when web's NODE_ENV conflicts, even with fully valid database config", async () => {
    writeManaged(path.join(webDir, ".env"), "NODE_ENV=development\n");

    // The test runner itself may already have NODE_ENV set (vitest sets
    // NODE_ENV=test); that would count as an already-resolved OS-level
    // value and mask the fixture file's NODE_ENV entirely (a file never
    // overrides an already-set value) — delete it so the file is the ONLY
    // source, and deployment's own "production" default plus the file's
    // "development" are what actually conflict.
    const env = { ...process.env };
    delete env.NODE_ENV;

    const result = await runToCompletion("node", ["--require", spawnInterceptorPath, deployScriptPath], {
      cwd: repoRoot,
      env: {
        ...env,
        API_PORT: "5302",
        WEB_PORT: "5303",
        API_CORS_ORIGIN: "http://localhost:5303",
        NEXT_PUBLIC_API_URL: "http://localhost:5302",
        CONTROL_DATABASE_URL: "postgresql://u:p@localhost:5432/relis_control",
      },
      timeoutMs: 10000,
    });

    expect(result.exitCode).toBe(1);
    expect(parseCaptured(result.stdout)).toBeNull();
    const diagnostic = JSON.parse(result.stderr.trim());
    expect(diagnostic).toMatchObject({ code: "CONFIG_INVALID", process: "web" });
    expect(diagnostic.variables).toContain("NODE_ENV");
  });

  it("forwards the exact resolved CONTROL_DATABASE_URL (from a file) to the real migration step's first spawn", async () => {
    writeManaged(path.join(databaseDir, ".env"), "CONTROL_DATABASE_URL=postgresql://u:p@localhost:5432/from_file_e2e\n");

    const result = await runToCompletion(
      "node",
      ["--require", spawnInterceptorPath, deployScriptPath, "--skip-build", "--skip-worker"],
      {
        cwd: repoRoot,
        env: {
          ...process.env,
          API_PORT: "5304",
          WEB_PORT: "5305",
          API_CORS_ORIGIN: "http://localhost:5305",
          NEXT_PUBLIC_API_URL: "http://localhost:5304",
        },
        timeoutMs: 10000,
      },
    );

    const captured = parseCaptured(result.stdout);
    expect(captured).not.toBeNull();
    // The migrate step is the first thing spawned (build/worker skipped,
    // start-services never reached since spawn is intercepted).
    expect(captured.args.join(" ")).toContain(path.join("packages", "database", "src", "migrate.ts"));
    expect(captured.env.CONTROL_DATABASE_URL).toBe("postgresql://u:p@localhost:5432/from_file_e2e");
  });
});

import { afterEach, describe, expect, it } from "vitest";
import { spawn, type ChildProcessWithoutNullStreams } from "node:child_process";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { startAndSupervise } from "../../../tooling/scripts/deploy.mjs";

// Proves startAndSupervise's REAL process-tree cleanup guarantees using
// real, harmless local subprocesses (never application services, never a
// real database or deployment) — deliberately NOT relying only on mocked
// kill() calls, per the explicit requirement for this file. See
// deployment.test.ts for the separate, faster, injected-fake-child tests
// that exercise pure ordering logic.
//
// Fixtures (tests/fixtures/runtime-config/):
//  - harmless-long-runner.mjs: sleeps forever; can self-exit after a delay
//    (--exit-after) or ignore SIGTERM (--ignore-sigterm).
//  - harmless-wrapper.mjs: mimics apps/web/scripts/run.mjs's relationship
//    to its Next child — spawns a harmless-long-runner grandchild,
//    forwards SIGINT/SIGTERM to it, and waits for it (with its own bounded
//    escalation). --detach-child spawns that grandchild detached (its own
//    process group / outside any Windows job object tied to the wrapper),
//    constructing a deliberately adversarial case: killing the wrapper can
//    NEVER automatically cascade to a detached grandchild, so cleanup can
//    only happen via startAndSupervise's own explicit tree-kill logic —
//    this is this file's "uncooperative" case.

const here = path.dirname(fileURLToPath(import.meta.url));
const fixturesDir = path.join(here, "..", "..", "fixtures", "runtime-config");
const wrapperPath = path.join(fixturesDir, "harmless-wrapper.mjs");
const longRunnerPath = path.join(fixturesDir, "harmless-long-runner.mjs");

function isAlive(pid: number | undefined): boolean {
  if (pid === undefined) return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

async function waitUntil(predicate: () => boolean, timeoutMs = 8000, intervalMs = 50): Promise<boolean> {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    if (predicate()) return true;
    await new Promise((resolve) => setTimeout(resolve, intervalMs));
  }
  return predicate();
}

/** Captures a spawned fixture's own stdout so its printed pid(s) can be read. */
function makeCapturingSpawnFn() {
  const outputs = new Map<string, string>();
  const children: ChildProcessWithoutNullStreams[] = [];

  function spawnFn(command: string, args: string[], options: Record<string, unknown>) {
    const child = spawn(command, args, { ...options, stdio: ["ignore", "pipe", "inherit"] }) as ChildProcessWithoutNullStreams;
    children.push(child);
    outputs.set(args.join(" "), "");
    child.stdout.on("data", (chunk: Buffer) => {
      outputs.set(args.join(" "), (outputs.get(args.join(" ")) ?? "") + chunk.toString());
    });
    return child;
  }

  function pidFrom(args: string[], label: string): number | undefined {
    const output = outputs.get(args.join(" ")) ?? "";
    const match = output.match(new RegExp(`${label}:(\\d+)`));
    return match ? Number(match[1]) : undefined;
  }

  return { spawnFn, pidFrom, children };
}

// Safety net: force-clean any fixture process left alive if an assertion
// throws mid-test, so a failing test never leaks a real background
// process. Uses the OS-appropriate mechanism directly (not
// startAndSupervise itself, to stay independent of the code under test).
const stragglers: number[] = [];
afterEach(async () => {
  for (const pid of stragglers.splice(0)) {
    if (!isAlive(pid)) continue;
    if (process.platform === "win32") {
      await new Promise<void>((resolve) => {
        const killer = spawn("taskkill", ["/pid", String(pid), "/T", "/F"], { stdio: "ignore" });
        killer.on("exit", () => resolve());
        killer.on("error", () => resolve());
      });
    } else {
      try {
        process.kill(-pid, "SIGKILL");
      } catch {
        try {
          process.kill(pid, "SIGKILL");
        } catch {
          /* already gone */
        }
      }
    }
  }
});

describe("startAndSupervise (real, harmless local subprocesses — no application services, no real database/deployment)", () => {
  it("cleans up a wrapper AND its grandchild on a cooperative requested shutdown", async () => {
    const { spawnFn, pidFrom } = makeCapturingSpawnFn();
    const wrapperArgs = [wrapperPath];

    const supervisor = startAndSupervise(
      [{ name: "wrapper", command: process.execPath, args: wrapperArgs, env: process.env, cwd: fixturesDir }],
      { spawnFn, gracePeriodMs: 3000 },
    );

    await waitUntil(() => pidFrom(wrapperArgs, "CHILD_PID") !== undefined);
    const wrapperPid = pidFrom(wrapperArgs, "WRAPPER_PID");
    const grandchildPid = pidFrom(wrapperArgs, "CHILD_PID");
    stragglers.push(wrapperPid!, grandchildPid!);

    expect(isAlive(wrapperPid)).toBe(true);
    expect(isAlive(grandchildPid)).toBe(true);

    const exitCode = await supervisor.requestShutdown("SIGTERM");

    expect(exitCode).toBe(0);
    expect(isAlive(wrapperPid)).toBe(false);
    expect(isAlive(grandchildPid)).toBe(false);
  }, 15000);

  it("cleans up an UNCOOPERATIVE wrapper's grandchild on requested shutdown (detached — escapes any automatic tree cascade)", async () => {
    const { spawnFn, pidFrom } = makeCapturingSpawnFn();
    const wrapperArgs = [wrapperPath, "--detach-child"];

    const supervisor = startAndSupervise(
      [{ name: "wrapper", command: process.execPath, args: wrapperArgs, env: process.env, cwd: fixturesDir }],
      { spawnFn, gracePeriodMs: 3000 },
    );

    await waitUntil(() => pidFrom(wrapperArgs, "CHILD_PID") !== undefined);
    const wrapperPid = pidFrom(wrapperArgs, "WRAPPER_PID");
    const grandchildPid = pidFrom(wrapperArgs, "CHILD_PID");
    stragglers.push(wrapperPid!, grandchildPid!);

    expect(isAlive(wrapperPid)).toBe(true);
    expect(isAlive(grandchildPid)).toBe(true);

    const exitCode = await supervisor.requestShutdown("SIGTERM");

    expect(exitCode).toBe(0);
    // The whole point of the detached grandchild: it CANNOT be cleaned up
    // by the wrapper dying alone (no automatic cascade is possible). If
    // this passes, startAndSupervise's own explicit tree-kill logic (not
    // an incidental platform side effect) is what did it.
    expect(isAlive(wrapperPid)).toBe(false);
    expect(isAlive(grandchildPid)).toBe(false);
  }, 15000);

  it("tears down a sibling wrapper (and its grandchild) when another service exits unexpectedly", async () => {
    const { spawnFn, pidFrom } = makeCapturingSpawnFn();
    const wrapperArgs = [wrapperPath];
    const selfExitingArgs = [longRunnerPath, "--exit-after", "600"];

    const supervisor = startAndSupervise(
      [
        { name: "wrapper", command: process.execPath, args: wrapperArgs, env: process.env, cwd: fixturesDir },
        { name: "self-exiting", command: process.execPath, args: selfExitingArgs, env: process.env, cwd: fixturesDir },
      ],
      { spawnFn, gracePeriodMs: 3000 },
    );

    await waitUntil(() => pidFrom(wrapperArgs, "CHILD_PID") !== undefined);
    const wrapperPid = pidFrom(wrapperArgs, "WRAPPER_PID");
    const grandchildPid = pidFrom(wrapperArgs, "CHILD_PID");
    stragglers.push(wrapperPid!, grandchildPid!);

    expect(isAlive(wrapperPid)).toBe(true);
    expect(isAlive(grandchildPid)).toBe(true);

    // "self-exiting" exits on its own after 600ms — an unexpected exit
    // that must tear down the wrapper sibling and everything IT owns too.
    const exitCode = await supervisor.exitPromise;

    expect(exitCode).not.toBe(0);
    expect(isAlive(wrapperPid)).toBe(false);
    expect(isAlive(grandchildPid)).toBe(false);
  }, 15000);

  it("tears down a sibling wrapper (and its grandchild) when another service fails to spawn", async () => {
    const { spawnFn, pidFrom } = makeCapturingSpawnFn();
    const wrapperArgs = [wrapperPath];

    const supervisor = startAndSupervise(
      [
        { name: "wrapper", command: process.execPath, args: wrapperArgs, env: process.env, cwd: fixturesDir },
        { name: "bad", command: "this-command-does-not-exist-12345", args: [], env: process.env, cwd: fixturesDir },
      ],
      { spawnFn, gracePeriodMs: 3000 },
    );

    await waitUntil(() => pidFrom(wrapperArgs, "CHILD_PID") !== undefined);
    const wrapperPid = pidFrom(wrapperArgs, "WRAPPER_PID");
    const grandchildPid = pidFrom(wrapperArgs, "CHILD_PID");
    stragglers.push(wrapperPid!, grandchildPid!);

    const exitCode = await supervisor.exitPromise;

    expect(exitCode).not.toBe(0);
    expect(isAlive(wrapperPid)).toBe(false);
    expect(isAlive(grandchildPid)).toBe(false);
  }, 15000);

  it("never touches an unrelated process: a plain uninvolved long-runner survives a supervised shutdown", async () => {
    // Spawned entirely OUTSIDE startAndSupervise, to prove termination is
    // scoped strictly to the pids this function itself spawned.
    const bystander = spawn(process.execPath, [longRunnerPath], { stdio: "ignore" });
    await new Promise((resolve) => setTimeout(resolve, 300));
    expect(isAlive(bystander.pid)).toBe(true);

    const { spawnFn, pidFrom } = makeCapturingSpawnFn();
    const wrapperArgs = [wrapperPath];
    const supervisor = startAndSupervise(
      [{ name: "wrapper", command: process.execPath, args: wrapperArgs, env: process.env, cwd: fixturesDir }],
      { spawnFn, gracePeriodMs: 3000 },
    );
    await waitUntil(() => pidFrom(wrapperArgs, "CHILD_PID") !== undefined);
    stragglers.push(pidFrom(wrapperArgs, "WRAPPER_PID")!, pidFrom(wrapperArgs, "CHILD_PID")!);

    await supervisor.requestShutdown("SIGTERM");

    expect(isAlive(bystander.pid)).toBe(true);

    bystander.kill("SIGKILL");
    await waitUntil(() => !isAlive(bystander.pid));
  }, 15000);
});

