62	/**
63	 * Resolves every selected process's effective configuration independently
64	 * from the SAME base environment snapshot (mirroring check-ports — see
65	 * packages/config/src/ports.ts): apps/api, apps/web, apps/worker, AND the
66	 * control database (packages/database), each via `resolveEffectiveEnv`
67	 * with the same root/package/tier precedence the standalone entry points
68	 * themselves use — not read directly from `baseEnv`/`process.env`, which
69	 * would silently ignore any `.env` file those entry points would
70	 * otherwise have honored.
71	 *
72	 * Validates each with its own existing schema (no duplicated rules), plus
73	 * apps/web's additional NODE_ENV-consistency rule (the same one
74	 * apps/web/scripts/run.mjs enforces on itself), and checks for a port
75	 * conflict between apps/api and apps/web. Nothing is spawned as part of
76	 * this function: a failure here — including a failure to even RESOLVE an
77	 * environment, not just to validate one — must prevent every subsequent
78	 * build/migrate/start step, and is always reported as a safe diagnostic,
79	 * never a raw exception or value.
80	 *
81	 * On success, every returned env has its NODE_ENV explicitly set to the
82	 * exact `mode` used here for tier selection. Each entry point re-runs its
83	 * own (lenient) env-file resolution when it starts; explicitly forcing
84	 * NODE_ENV to the already-decided mode means that re-resolution can only
85	 * ever confirm the same mode, never silently diverge to a different one.
86	 */
87	export function validateDeployment(baseEnv, options = {}) {
88	  let mode;
89	  let apiEnv;
90	  let webEnv;
91	  let workerEnv;
92	  let databaseEnv;
93	
94	  try {
95	    // Initial mode selection is INSIDE the safe boundary too: an
96	    // invalid/empty OS-provided NODE_ENV must produce the same structured,
97	    // value-free diagnostic as every other failure here, not escape as an
98	    // uncaught exception.
99	    mode = validateRuntimeMode(baseEnv.NODE_ENV, "production", "deploy");
100	    apiEnv = resolveEffectiveEnv(mode, apiDir, baseEnv);
101	    webEnv = resolveEffectiveEnv(mode, webDir, baseEnv);
102	    workerEnv = resolveEffectiveEnv(mode, workerDir, baseEnv);
103	    databaseEnv = resolveEffectiveEnv(mode, databaseDir, baseEnv);
104	
105	    loadApiConfig(apiEnv);
106	    loadWorkerConfig(workerEnv);
107	    loadWebRuntimeConfig(webEnv);
108	    parsePublicWebConfig({ NEXT_PUBLIC_API_URL: webEnv.NEXT_PUBLIC_API_URL });
109	    // The same rule apps/web/scripts/run.mjs enforces on itself: an
110	    // invalid/empty/conflicting file-provided NODE_ENV must be rejected
111	    // here too, before any deployment side effect — not only when
112	    // apps/web happens to be started directly.
113	    validateConsistentRuntimeMode(webEnv.NODE_ENV, mode);
114	    checkPortConflicts(apiEnv, webEnv);
115	    if (!options.skipMigrate) {
116	      // Only the control database is migrated automatically here: the
117	      // project schema is applied per-project (see README "Migration"),
118	      // not as a single global deploy step, and is out of scope.
119	      loadDatabaseConfigForTarget("control", databaseEnv);
120	    }
121	  } catch (error) {
122	    if (error instanceof ConfigValidationError || error instanceof PortConflictError) {
123	      return { ok: false, diagnostic: error.toDiagnostic(), mode, apiEnv, webEnv, workerEnv, databaseEnv };
124	    }
125	    // An unexpected failure (e.g. an I/O error resolving a .env file)
126	    // must still produce a safe, value-free diagnostic instead of letting
127	    // a raw exception — and whatever it might contain — propagate.
128	    return {
129	      ok: false,
130	      diagnostic: { code: "CONFIG_INVALID", process: "deploy", categories: ["runtime"], variables: [] },
131	      mode,
132	      apiEnv,
133	      webEnv,
134	      workerEnv,
135	      databaseEnv,
136	    };
137	  }
138	
139	  apiEnv.NODE_ENV = mode;
140	  webEnv.NODE_ENV = mode;
141	  workerEnv.NODE_ENV = mode;
142	  databaseEnv.NODE_ENV = mode;
143	
144	  return { ok: true, diagnostic: null, mode, apiEnv, webEnv, workerEnv, databaseEnv };
145	}
