  if (!isPidAlive(pid)) return true;
  for (let attempt = 0; attempt < MAX_DESCENDANT_KILL_ATTEMPTS; attempt++) {
    await killFn(pid, "SIGKILL");
    if (await waitForPidExit(pid, gracePeriodMs)) return true;
  }
  return !isPidAlive(pid);
}

