/**
 * Spawns every service and supervises the group's lifecycle:
 *  - If one fails to spawn or exits unexpectedly (before a requested
 *    shutdown), every other still-running service (and everything each
 *    one owns) is terminated, and the returned promise resolves nonzero
 *    only AFTER every service has been confirmed to have actually exited
 *    (not merely "asked to").
 *  - A requested shutdown (`requestShutdown`, wired to SIGINT/SIGTERM by
 *    the caller) terminates every service the same way and resolves 0
 *    once all have exited.
 *  - Termination is bounded, in two steps, and the second step ALWAYS
 *    runs regardless of how the first went: (1) a cooperative signal
 *    (`child.kill(signal)`), giving a well-behaved process — including
 *    apps/web's wrapper, which forwards it to its own Next child — a
 *    chance to shut down its own tree on its own, bounded by
 *    `gracePeriodMs`; then (2) an unconditional, platform-appropriate
 *    tree-kill (`killProcessTree`) targeting the same pid. Step 2 is not
 *    an "if step 1 failed" escalation: a direct child can appear to exit
 *    immediately (on Windows, a non-SIGKILL signal terminates the direct
 *    child outright, before it can forward anything to what it spawned)
 *    while still leaving a descendant it owns running — step 2 is what
 *    actually guarantees no descendant survives, and is a cheap no-op
 *    when the tree is already fully gone.
 *  - Never signals anything beyond the specific pids this function itself
 *    spawned (and their descendants) — no broad or name-based process
 *    lookup is ever used.
 *
 * `options.spawnFn` is injectable so tests can simulate spawn failures
 * without depending on a specific missing executable; `options.killFn` is
 * injectable so lifecycle-ordering tests can observe termination calls
 * without real process trees, while separate tests use the real
 * `killProcessTree` against harmless local fixtures to prove actual OS
 * -level cleanup.
 */
export function startAndSupervise(services, options = {}) {
  const spawnFn = options.spawnFn ?? defaultSpawnService;
  const killFn = options.killFn ?? killProcessTree;
  const gracePeriodMs = options.gracePeriodMs ?? DEFAULT_SHUTDOWN_GRACE_MS;

  const entries = new Map();
  let shuttingDown = false;
  let settled = false;
  let finalCode = 0;
  let resolveExit;
  const exitPromise = new Promise((resolve) => {
    resolveExit = resolve;
  });

  function allExited() {
    for (const entry of entries.values()) {
      if (!entry.exited) return false;
    }
    return true;
  }

  function maybeFinish() {
    if (settled || !allExited()) return;
    settled = true;
    resolveExit(finalCode);
  }

  async function terminate(entry, signal) {
    if (entry.exited) return;
    const { child } = entry;
    const pid = child.pid;

    if (process.platform === "win32") {
      // On Windows, child.kill(signal) for any non-SIGKILL signal
      // terminates the DIRECT child immediately, regardless of any
      // handler it registered (confirmed: a registered SIGTERM handler
      // never runs). By the time it has exited, Windows can no longer
      // enumerate its children by parent pid to clean them up — a
      // "cooperative signal, escalate on timeout" ordering would kill the
      // parent before its own descendants could ever be found. Run the
      // guaranteed tree-kill FIRST instead, while the process (and its
      // recorded parent/child relationships) still exist. Still also call
      // child.kill() itself afterward: harmless (a no-op) once the tree-kill
      // has already terminated the process, and it is what a test's
      // injected fake child relies on to simulate its own exit.
      if (pid !== undefined) {
        await killFn(pid, "SIGKILL");
      }
      if (child.exitCode === null && child.signalCode === null) {
        child.kill(signal ?? "SIGTERM");
      }
      await waitForChildExit(child, gracePeriodMs);
      return;
    }

    // POSIX: signal the whole process group (this child was spawned as
    // its own group leader — see defaultSpawnService), not just the
    // direct child, so a well-behaved process AND everything it owns gets
    // a genuine chance to shut down cooperatively first.
    if (child.exitCode === null && child.signalCode === null) {
      try {
        process.kill(-pid, signal ?? "SIGTERM");
      } catch {
        child.kill(signal ?? "SIGTERM");
      }
    }
    if (await waitForChildExit(child, gracePeriodMs)) return;
    // The cooperative signal did not bring the process (or its tree) down
    // in time: force a guaranteed tree-kill instead of waiting
    // indefinitely or leaving anything running.
    if (pid !== undefined) {
      await killFn(pid, "SIGKILL");
      await waitForChildExit(child, gracePeriodMs);
    }
  }

  function terminateAll(signal) {
    shuttingDown = true;
    return Promise.all([...entries.values()].map((entry) => terminate(entry, signal)));
  }

  for (const service of services) {
    const child = spawnFn(service.command, service.args, {
      stdio: service.stdio ?? "inherit",
      env: service.env,
      cwd: service.cwd,
    });
    const entry = { child, exited: false };
    entries.set(service.name, entry);

    const onError = () => {
      console.error(JSON.stringify({ code: "SERVICE_SPAWN_FAILED", service: service.name }));
      entry.exited = true; // a spawn error means there is no real process to wait for
      finalCode = finalCode || 1;
      if (!shuttingDown) void terminateAll();
      maybeFinish();
    };

    const onExit = (code) => {
      const wasAlreadyShuttingDown = shuttingDown;
      entry.exited = true;
      if (!wasAlreadyShuttingDown) {
        console.error(JSON.stringify({ code: "SERVICE_EXITED_UNEXPECTEDLY", service: service.name }));
        finalCode = code && code !== 0 ? code : 1;
        void terminateAll();
      }
      maybeFinish();
    };

    child.once("error", onError);
    child.once("exit", onExit);
  }

  function requestShutdown(signal) {
    if (!shuttingDown) void terminateAll(signal);
    return exitPromise;
  }

  maybeFinish(); // handles the (degenerate) zero-services case

  return { exitPromise, requestShutdown };
}

