          WEB_PORT: "5305",
          API_CORS_ORIGIN: "http://localhost:5305",
          NEXT_PUBLIC_API_URL: "http://localhost:5304",
        },
        timeoutMs: 10000,
      },
    );

    const captured = parseCaptured(result.stdout);
    expect(captured).not.toBeNull();
