import { defineConfig } from "prisma/config";

// CONTROL_DATABASE_URL is resolved and validated by @relis/config's shared
// database contract (see packages/database/src/migrate.ts) before the
// Prisma CLI is ever invoked; it is expected to already be present in
// process.env by that point.
export default defineConfig({
  schema: "schema.prisma",
  migrations: {
    path: "migrations",
  },
  datasource: {
    url: process.env.CONTROL_DATABASE_URL,
  },
});

// Control-plane database schema. No models are defined yet: no
// control-plane domain has been authorized for implementation. This
// schema exists only so the Prisma CLI has a valid target for the
// migration entry point (packages/database/src/migrate.ts) to validate
// configuration against and invoke `prisma migrate deploy` on.
datasource db {
  provider = "postgresql"
}

